      subjects:[['Web Development',12,8,72,'6h 40m','code-2'],['Networking',8,5,61,'3h 15m','network'],['Cybersecurity',7,4,54,'2h 50m','shield-check'],['Mathematics',10,6,49,'4h 05m','sigma'],['English',5,3,63,'2h 20m','book-open']],
      notifications:[{title:'Task deadline approaching',body:'Finish Laravel Authentication is due today.',time:'12 min ago',read:false,icon:'clock-3'},{title:'You completed a focus session',body:'45 minutes of deep work added to your week.',time:'Yesterday',read:false,icon:'check-circle-2'},{title:'7-day streak achieved',body:'You showed up every day this week.',time:'Mon',read:true,icon:'flame'},{title:'Goal milestone completed',body:'You checked CRUD off your Laravel goal.',time:'Sun',read:true,icon:'target'}],
