    let state=loadState(), view='dashboard', search='', taskFilter='All', plannerWeekOffset=0, timer={running:false,seconds:0,elapsedSeconds:0,startedAt:null,runningSince:null,taskId:1,interval:null}, focusComplete=null;window.state=state;
    function loadState(){const saved=window.StudyFlowStorage.read({}),loaded=window.StudyFlowState.initialize(seed),weekStart=window.StudyFlowUtils.dateKey(window.StudyFlowUtils.startOfWeek());if(saved.settings?.demo===false&&!Array.isArray(saved.studySessions))loaded.studySessions=[];if(saved.settings?.demo!==false&&Array.isArray(loaded.plannerSessions)&&loaded.plannerSessions.some(session=>session.id?.startsWith('demo-')&&session.date<weekStart))loaded.plannerSessions=window.StudyFlowUtils.clone(seed.plannerSessions);return loaded}
    function save(){state=window.StudyFlowState.update(state);window.state=state;if(!window.StudyFlowState.persist())toast('Could not save changes')}
    function icon(name,size=''){return `<i data-lucide="${name}" class="${size}"></i>`}
    function refreshIcons(){
      if(window.lucide)lucide.createIcons();
      const form=document.querySelector('#modal-root form'),due=form?.querySelector('select[name="due"]'),plannerDate=form?.querySelector('select[name="date"]');
      if(due&&!due.dataset.dynamic){const selected=due.value;due.innerHTML=taskDueOptions(selected);due.dataset.dynamic='true';const estimate=document.createElement('label');estimate.className='form-label';estimate.innerHTML='Estimated minutes<input name="estimate" type="number" min="5" max="240" step="5" required>';const task=state.tasks.find(item=>item.title===form.elements.title.value);estimate.querySelector('input').value=task?.estimate||45;due.before(estimate)}
      if(plannerDate&&!plannerDate.dataset.dynamic){const selected=plannerDate.value;plannerDate.innerHTML=plannerOptions(selected);plannerDate.dataset.dynamic='true'}
      const dialog=document.querySelector('#modal-root .modal');if(dialog&&!dialog.dataset.accessible){dialog.setAttribute('role','dialog');dialog.setAttribute('aria-modal','true');const heading=dialog.querySelector('.modal-head h2');if(heading){heading.id='studyflow-dialog-title';dialog.setAttribute('aria-labelledby',heading.id)}dialog.dataset.accessible='true';dialog.querySelector('input,select,textarea')?.focus()}
    }
    function toast(message){const el=document.createElement('div');el.className='toast';el.innerHTML=icon('check-circle-2')+`<span>${message}</span>`;document.getElementById('toast-root').append(el);setTimeout(()=>el.remove(),2800)}
    function nav(){const items=[['dashboard','Dashboard','layout-dashboard'],['tasks','Tasks','check-square-2'],['subjects','Subjects','layers-3'],['goals','Goals','target'],['planner','Planner','calendar-days'],['focus','Focus','timer'],['analytics','Analytics','chart-no-axes-combined']];return `<aside class="sidebar"><div class="brand"><span class="brand-mark">${icon('orbit')}</span>StudyFlow</div><div class="nav-label">Workspace</div><nav class="nav">${items.map(i=>`<button class="${view===i[0]?'active':''}" onclick="go('${i[0]}')">${icon(i[2])}<span>${i[1]}</span></button>`).join('')}</nav><div class="sidebar-bottom"><button onclick="go('notifications')">${icon('bell')}<span>Notifications</span>${state.notifications.some(n=>!n.read)?'<b class="dot"></b>':''}</button><button onclick="go('settings')">${icon('settings-2')}<span>Settings</span></button><div class="profile"><span class="avatar">DS</span><div><strong>Daffi S.</strong><small>Student account</small></div>${icon('more-horizontal')}</div></div></aside>`}
    function topbar(){const titles={dashboard:'Dashboard',tasks:'Tasks',subjects:'Subjects',goals:'Goals',planner:'Planner',focus:'Focus mode',analytics:'Analytics',notifications:'Notifications',settings:'Settings'};return `<header class="topbar"><div class="crumb"><button class="mobile-menu" onclick="openCommand()">${icon('menu')}</button><strong>${titles[view]}</strong><span class="demo-pill">Demo mode</span></div><div class="top-actions"><button class="search-trigger" onclick="openCommand()"><span>${icon('search')}Search</span><span class="key">⌘ K</span></button><button class="icon-btn" onclick="openModal('task')" aria-label="Quick add">${icon('plus')}</button><button class="icon-btn" onclick="go('notifications')" aria-label="Notifications">${icon('bell')}${state.notifications.some(n=>!n.read)?'<b class="dot"></b>':''}</button><span class="avatar">DS</span></div></header>`}
    function decorateAppChrome(){const demoPill=document.querySelector('.demo-pill'),shortcut=document.querySelector('.search-trigger .key');if(demoPill)demoPill.hidden=!state.settings.demo;if(shortcut)shortcut.textContent=/Mac|iPhone|iPad/.test(navigator.platform)?'⌘ K':'Ctrl K';document.querySelectorAll('.setting-row').forEach(row=>{const toggle=row.querySelector('.toggle'),label=row.querySelector('strong');if(toggle&&label){toggle.setAttribute('aria-label',label.textContent);toggle.setAttribute('aria-pressed',toggle.classList.contains('on'))}})}
    function layout(content){document.getElementById('app').innerHTML=nav()+`<main class="main">${topbar()}<section class="content">${content}</section></main><nav class="mobile-nav">${[['dashboard','Home','house'],['tasks','Tasks','check-square-2'],['planner','Plan','calendar-days'],['focus','Focus','timer'],['analytics','Stats','chart-no-axes-combined']].map(i=>`<button class="${view===i[0]?'active':''}" onclick="go('${i[0]}')">${icon(i[2])}<span>${i[1]}</span></button>`).join('')}</nav>`;refreshIcons();decorateAppChrome()}
    function pageHead(eyebrow,title,sub,button=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div>${button}</div>`}
    function recommendationDetails(){return window.StudyFlowPriorityEngine.recommend(state.tasks)}
    function recommendation(){return recommendationDetails().task||{id:null,title:'No open tasks',subject:'No subject',priority:'',due:'',estimate:0,progress:0,done:true}}
    function studyActivity(){return window.StudyFlowAnalytics.lastSevenDays(state.studySessions||[])}
    function completedStudyMinutes(sessions=state.studySessions||[]){return window.StudyFlowAnalytics.studyMinutes(sessions)}
    function renderStudyBars(days,className='big-chart'){const max=Math.max(...days.map(day=>day.minutes),1);return `<div class="${className}">${days.map(day=>`<div class="bar-col"><i style="height:${Math.max(day.minutes?8:0,day.minutes/max*100)}%"></i><small>${window.StudyFlowUtils.formatDate(day.date,{weekday:'short'})}</small></div>`).join('')}</div>`}
    function goalProgress(goal){return window.StudyFlowGoals.progress(goal)}
    function taskRow(t){return `<div class="task-row"><button class="check ${t.done?'done':''}" onclick="toggleTask(${t.id})" aria-label="${t.done?'Reopen':'Complete'} ${t.title}">${t.done?icon('check'):''}</button><div class="task-copy"><strong class="${t.done?'done':''}">${t.title}</strong><small><span>${t.subject}</span><span>·</span><span class="tag ${t.priority==='High'?'':'green'}">${t.priority}</span></small></div><div class="task-end"><small>${t.due}</small><div class="bar"><i style="width:${t.done?100:t.progress}%"></i></div></div></div>`}
    function dashboard(){
      const details=recommendationDetails(),next=details.task,done=window.StudyFlowAnalytics.completed(state.tasks),total=state.tasks.length,pct=window.StudyFlowAnalytics.completionRate(state.tasks),activity=studyActivity(),minutes=activity.reduce((sum,day)=>sum+day.minutes,0),streak=window.StudyFlowAnalytics.studyStreak(state.studySessions||[]);
      const today=window.StudyFlowUtils.formatDate(new Date()),bestWindow=window.StudyFlowAnalytics.bestFocusWindow(state.studySessions||[]),upcoming=window.StudyFlowAnalytics.upcomingDeadlines(state.tasks),goalPercent=state.goals.length?Math.round(state.goals.reduce((sum,goal)=>sum+goalProgress(goal),0)/state.goals.length):0;
      const nextMove=next?`<div class="panel-kicker"><span>${icon('sparkles')} Your next best move</span><span class="tag">Score ${details.score}</span></div><div class="move-title">${window.StudyFlowUtils.escape(next.title)}</div><p class="move-desc">${window.StudyFlowUtils.formatDeadline(next.due)} · ${next.priority} importance · ${next.estimate} min</p><div class="why-task"><strong>Why this task?</strong><ul>${details.reasons.map(reason=>`<li>${window.StudyFlowUtils.escape(reason)}</li>`).join('')}</ul></div><div class="move-meta"><div class="meta-item"><small>Priority</small><strong>${next.priority}</strong></div><div class="meta-item"><small>Progress</small><strong>${next.progress}%</strong></div><div class="meta-item"><small>Subject</small><strong>${window.StudyFlowUtils.escape(next.subject)}</strong></div></div><div><button class="primary" onclick="startFocus(${next.id})">${icon('play')} Start focus</button><button class="secondary" onclick="go('tasks')" style="margin-left:6px">View task</button></div>`:`<div class="panel-kicker">Your next best move</div><div class="move-title">You are all caught up.</div><p class="move-desc">Add a task when new work comes in.</p><button class="primary" onclick="openModal('task')">${icon('plus')} Create task</button>`;
      const activityContent=minutes?`${renderStudyBars(activity,'activity-chart')}<div class="insight">${icon('lightbulb')}<span>Your most active hour is <strong>${bestWindow}</strong>.</span></div>`:`<div class="empty"><strong>No study data yet</strong><span>Complete a focus session to start building your analytics.</span></div>`;
      return `<div class="view">${pageHead(today,'Good morning, Daffi.','Here is what matters today.','<button class="primary" onclick="openModal(\'task\')">'+icon('plus')+'<span>Quick add</span></button>')}<div class="dashboard-grid"><section class="panel move-panel">${nextMove}</section><section class="panel hero-panel"><div class="eyebrow" style="color:var(--accent)">Today at a glance</div><h2>A little progress, every day.</h2><p>Your academic rhythm is taking shape. Keep the promise you made to yourself this morning.</p><div class="hero-bottom"><div class="progress-label"><div class="progress-ring"><svg viewBox="0 0 88 88"><circle class="track" cx="44" cy="44" r="36"></circle><circle class="value" cx="44" cy="44" r="36" style="stroke-dashoffset:${226-(226*pct/100)}"></circle></svg><strong>${pct}%</strong></div><div><strong>${done} of ${total} tasks completed</strong><small>${pct>=50?'You are past the halfway point.':'Start with one small win.'}</small></div></div><span class="tag green">${icon('flame')} ${streak} day streak</span></div></section></div><div class="dashboard-lower"><section class="panel tasks-panel"><div class="panel-head"><h3>Today's tasks</h3><a onclick="go('tasks')">View all ${icon('arrow-up-right')}</a></div><div class="task-list">${state.tasks.filter(task=>!task.done).slice(0,5).map(taskRow).join('')||'<div class="empty"><strong>No tasks due today</strong></div>'}</div></section><section class="panel activity-panel"><div class="panel-head"><h3>Focus progress</h3><span class="muted">Last 7 days</span></div>${activityContent}</section></div><div class="stats-row"><div class="panel stat-card"><div><small>Study this week</small><strong>${formatMinutes(minutes)}</strong></div><span class="stat-icon">${icon('timer')}</span></div><div class="panel stat-card"><div><small>Upcoming deadlines</small><strong>${upcoming}</strong></div><span class="stat-icon">${icon('calendar-clock')}</span></div><div class="panel stat-card"><div><small>Goal progress</small><strong>${goalPercent}%</strong></div><span class="stat-icon">${icon('target')}</span></div></div></div>`
    }
    function formatMinutes(m){return `${Math.floor(m/60)}h ${String(m%60).padStart(2,'0')}m`}
    function tasks(){let list=state.tasks.filter(t=>(taskFilter==='All'||t.priority===taskFilter)&&(`${t.title} ${t.subject}`).toLowerCase().includes(search.toLowerCase()));return `<div class="view">${pageHead('Workspace','Tasks','Keep the important work visible and moving.','<button class="primary" onclick="openModal(\'task\')">'+icon('plus')+'<span>New task</span></button>')}<div class="toolbar"><div class="input-wrap">${icon('search')}<input class="input" placeholder="Search tasks or subjects" value="${search}" oninput="search=this.value;render()"></div>${['All','High','Medium','Low'].map(x=>`<button class="${taskFilter===x?'primary':'secondary'}" onclick="taskFilter='${x}';render()">${x}</button>`).join('')}</div><section class="panel task-table"><div class="table-head"><span>Task</span><span>Subject</span><span>Priority</span><span>Deadline</span><span></span></div>${list.length?list.map(t=>`<div class="table-item"><div class="task-name"><button class="check ${t.done?'done':''}" onclick="toggleTask(${t.id})">${t.done?icon('check'):''}</button><div><strong class="${t.done?'done':''}">${t.title}</strong><small>${t.estimate} min · ${t.progress}% complete</small></div></div><small>${t.subject}</small><span class="tag ${t.priority==='High'?'':'green'}">${t.priority}</span><small>${t.due}</small><div class="action-row"><button class="mini-btn" onclick="startFocus(${t.id})" aria-label="Focus task">${icon('play')}</button><button class="mini-btn" onclick="deleteTask(${t.id})" aria-label="Delete task">${icon('trash-2')}</button></div></div>`).join(''):`<div class="empty">${icon('check-square')}<strong>No tasks yet</strong><span>Make space for the work that matters.</span></div>`}</section></div>`}
    function subjects(){const icons=new Map(state.subjects.map(subject=>[subject[0],subject[5]]));return `<div class="view">${pageHead('Your curriculum','Subjects','See the shape of your semester at a glance.')}<div class="view-grid">${state.subjects.map(subject=>{const tasks=state.tasks.filter(task=>task.subject===subject[0]),completed=window.StudyFlowAnalytics.completed(tasks),progress=window.StudyFlowAnalytics.completionRate(tasks),minutes=completedStudyMinutes((state.studySessions||[]).filter(session=>session.subject===subject[0]));return `<section class="panel subject-card"><div class="subject-top"><span class="subject-mark">${icon(icons.get(subject[0]))}</span></div><h3>${window.StudyFlowUtils.escape(subject[0])}</h3><p class="muted">${tasks.length} task${tasks.length===1?'':'s'} · ${completed} completed</p><div class="card-progress"><div class="bar"><i style="width:${progress}%"></i></div></div><div class="subject-foot"><div><strong>${progress}%</strong><small>Progress</small></div><div><strong style="font-size:15px">${formatMinutes(minutes)}</strong><small>Study time</small></div></div></section>`}).join('')||'<div class="empty"><strong>No subjects yet</strong><span>Add a task to connect work with a subject.</span></div>'}</div></div>`}
    function goals(){return `<div class="view">${pageHead('Longer horizon','Goals','Turn intention into a path you can actually walk.','<button class="primary" onclick="openModal(\'goal\')">'+icon('plus')+'<span>Create goal</span></button>')}<div class="view-grid">${state.goals.map(goal=>{const progress=goalProgress(goal);return `<section class="panel goal-card"><div class="goal-top"><div><span class="eyebrow">${progress===100?'Complete':'In progress'}</span><h3>${window.StudyFlowUtils.escape(goal.title)}</h3></div><span class="goal-percent">${progress}%</span><button class="mini-btn" onclick="deleteGoal(${goal.id})" aria-label="Delete ${window.StudyFlowUtils.escape(goal.title)}">${icon('trash-2')}</button></div><p>${window.StudyFlowUtils.escape(goal.description)}</p><div class="bar"><i style="width:${progress}%"></i></div><ul class="milestones">${goal.milestones.map((milestone,index)=>`<li class="${milestone[1]?'done':''}"><button type="button" class="milestone-toggle" aria-pressed="${milestone[1]}" onclick="toggleMilestone(${goal.id},${index})">${milestone[1]?icon('check-circle-2'):icon('circle')}<span>${window.StudyFlowUtils.escape(milestone[0])}</span></button></li>`).join('')}</ul></section>`}).join('')||'<div class="empty"><strong>No goals yet</strong><span>Turn a big academic target into manageable milestones.</span><button class="primary" onclick="openModal(\'goal\')">Create goal</button></div>'}</div></div>`}
    function planner(){const sessions=[['09:00','Laravel practice','day 1',''],['10:00','Networking','day 2','blue'],['15:30','Math review','day 4','coral'],['19:00','Deep focus','day 5','lav']];return `<div class="view">${pageHead('Plan the week','Planner','A calm week is a kind of superpower.','<button class="primary" onclick="openModal(\'session\')">'+icon('plus')+'<span>New session</span></button>')}<section class="panel planner"><div class="week-nav"><div><h3>Sep 30 - Oct 6, 2024</h3><span>Week 40 · 12h 45m planned</span></div><div><button class="secondary">${icon('chevron-left')}</button><button class="secondary" style="margin-left:5px">${icon('chevron-right')}</button></div></div><div class="calendar"><div></div>${['Mon 30','Tue 1','Wed 2','Thu 3','Fri 4','Sat 5','Sun 6'].map((d,i)=>`<div class="calendar-head ${i===1?'today':''}">${d.split(' ')[0]}<strong>${d.split(' ')[1]}</strong></div>`).join('')}<div class="time-col">${['09:00','10:00','11:00','12:00','13:00','14:00','15:00','16:00'].map(x=>`<div class="time">${x}</div>`).join('')}</div>${[0,1,2,3,4,5,6].map((d)=>`<div class="day-col">${sessions.filter(x=>x[2]===`day ${d+1}`).map(x=>`<div class="session ${x[3]}" style="top:${x[0]==='09:00'?12:x[0]==='10:00'?86:234}px;height:${x[0]==='15:30'?92:68}px"><strong>${x[1]}</strong><small>${x[0]} · 45 min</small></div>`).join('')}</div>`).join('')}</div><div class="agenda"><div class="agenda-day">Tuesday · October 1</div>${sessions.slice(0,2).map(x=>`<div class="agenda-session"><strong>${x[0]} · ${x[1]}</strong><small>45 min · Web Development</small></div>`).join('')}<div class="agenda-day">Thursday · October 3</div><div class="agenda-session" style="border-color:var(--coral);background:#fcebe7"><strong>15:30 · Math review</strong><small>50 min · Mathematics</small></div></div></section></div>`}
    function focus(){let t=state.tasks.find(x=>x.id===timer.taskId)||recommendation();return `<div class="view"><div class="focus-wrap"><div class="eyebrow">Quiet room · ${timer.running?'In session':'Ready when you are'}</div><h1>${timer.running?'Stay with it.':'Make room for deep work.'}</h1><div class="focus-orb"></div><div class="timer-label">${timer.running?'Focused on':'Next up'}</div><div class="timer">${timer.running?formatTimer(timer.seconds):'45:00'}</div><div class="focus-task"><div class="eyebrow">${t.subject}</div><h2>${t.title}</h2><p>${timer.running?'One clear block. Nothing else needs you right now.':'A focused 45 minute block will move this task forward.'}</p></div><div class="focus-controls">${timer.running?`<button class="secondary" onclick="pauseFocus()">${icon('pause')} Pause</button><button class="primary" onclick="finishFocus()">${icon('check')} Finish session</button>`:`<button class="primary" onclick="startFocus(${t.id})">${icon('play')} Start focus</button>`}<button class="secondary" onclick="cancelFocus()">${icon('x')} Cancel</button></div></div></div>`}
    function formatTimer(s){return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
    function analytics(){
      const sessions=state.studySessions||[],days=studyActivity(),minutes=days.reduce((sum,day)=>sum+day.minutes,0),windowLabel=window.StudyFlowAnalytics.bestFocusWindow(sessions),streak=window.StudyFlowAnalytics.studyStreak(sessions),hasData=minutes>0;
      const dayKeys=new Set(days.map(day=>day.key)),sessionCount=sessions.filter(session=>session.completed&&dayKeys.has(window.StudyFlowUtils.dateKey(new Date(session.startedAt)))).length;
      return `<div class="view">${pageHead('Reflect and improve','Analytics','Patterns become useful when you can see them.')}<div class="analytics-grid"><section class="panel metric-panel"><div class="panel-kicker">Study time · last 7 days</div><div class="metric">${formatMinutes(minutes)}</div><p>Across ${sessionCount} recorded focus session${sessionCount===1?'':'s'}</p>${hasData?renderStudyBars(days):'<div class="empty"><strong>No study data yet</strong><span>Complete a focus session to start building your analytics.</span></div>'}${hasData?`<div class="chart-note">${icon('lightbulb')} Your most active hour is <strong>${windowLabel}</strong>.</div>`:''}</section><section class="panel streak-panel"><div class="panel-kicker">Consistency <span>${icon('flame')}</span></div><div class="streak-number">${streak} <small>day streak</small></div><p class="muted">Based on completed focus sessions</p><div class="days">${days.map(day=>`<span class="${day.minutes?'on':''} ${day.key===window.StudyFlowUtils.dateKey()?'today':''}" title="${day.minutes} study minutes">${window.StudyFlowUtils.formatDate(day.date,{weekday:'short'}).slice(0,1)}</span>`).join('')}</div></section></div><div class="stats-row"><div class="panel stat-card"><div><small>Tasks completed</small><strong>${window.StudyFlowAnalytics.completed(state.tasks)}</strong></div><span class="stat-icon">${icon('check-check')}</span></div><div class="panel stat-card"><div><small>Top study subject</small><strong style="font-size:16px">${window.StudyFlowUtils.escape(window.StudyFlowAnalytics.topSubject(sessions))}</strong></div><span class="stat-icon">${icon('book-open')}</span></div><div class="panel stat-card"><div><small>Task completion</small><strong>${window.StudyFlowAnalytics.completionRate(state.tasks)}%</strong></div><span class="stat-icon">${icon('target')}</span></div></div></div>`
    }
    function notifications(){return `<div class="view">${pageHead('Stay in the loop','Notifications','Small signals that keep the system honest.','<button class="secondary" onclick="markAllRead()">'+icon('check-check')+' Mark all read</button>')}<section class="panel notification-list">${state.notifications.length?state.notifications.map((n,i)=>`<div class="notification ${n.read?'':'unread'}"><span class="notification-icon">${icon(n.icon)}</span><div><h4>${n.title}</h4><p>${n.body}</p></div><time>${n.time}</time>${!n.read?`<button class="mini-btn" onclick="markRead(${i})" aria-label="Mark as read">${icon('check')}</button>`:''}</div>`).join(''):`<div class="empty">${icon('bell-off')}<strong>You're all caught up</strong><span>New nudges will appear here.</span></div>`}</section></div>`}
    function settings(){return `<div class="view">${pageHead('Your preferences','Settings','Make StudyFlow feel like yours.')}<section class="panel settings-grid"><div class="setting-row"><div><strong>Focus sounds</strong><p>A soft signal when a session starts or ends.</p></div><button class="toggle ${state.settings.sound?'on':''}" onclick="toggleSetting('sound')"><i></i></button></div><div class="setting-row"><div><strong>Deadline reminders</strong><p>Get a gentle nudge the day a task is due.</p></div><button class="toggle ${state.settings.reminders?'on':''}" onclick="toggleSetting('reminders')"><i></i></button></div><div class="setting-row"><div><strong>Demo mode</strong><p>Keep realistic sample data ready for a walkthrough.</p></div><button class="toggle ${state.settings.demo?'on':''}" onclick="toggleSetting('demo')"><i></i></button></div><div class="setting-row"><div><strong>Reset demo data</strong><p>Return the workspace to its original state.</p></div><button class="secondary" onclick="resetData()">${icon('rotate-ccw')} Reset</button></div></section></div>`}
    function render(){const pages={dashboard,tasks,subjects,goals,planner,focus,analytics,notifications,settings};layout(pages[view]())}
    function go(next){view=next;search='';render();window.scrollTo({top:0,behavior:'smooth'})}
    function changePlannerWeek(offset){plannerWeekOffset+=offset;render()}
    function toggleTask(id){const t=state.tasks.find(task=>String(task.id)===String(id));if(!t)return;t.done=!t.done;t.progress=t.done?100:t.progress;save();toast(t.done?'Task completed':'Task reopened');render()}
    function deleteTask(id){state.tasks=state.tasks.filter(task=>String(task.id)!==String(id));save();toast('Task deleted');render()}
    function deleteGoal(id){state.goals=state.goals.filter(goal=>goal.id!==id);save();toast('Goal deleted');render()}
    function toggleMilestone(id,index){const g=state.goals.find(x=>x.id===id);g.milestones[index][1]=!g.milestones[index][1];g.progress=Math.round(g.milestones.filter(x=>x[1]).length/g.milestones.length*100);save();toast('Goal updated');render()}
    function toggleSetting(key){state.settings[key]=!state.settings[key];save();toast('Settings updated');render()}
    function markRead(i){state.notifications[i].read=true;save();render()};function markAllRead(){state.notifications.forEach(n=>n.read=true);save();toast('Notifications marked as read');render()}
    function resetData(){state=JSON.parse(JSON.stringify(seed));save();toast('Demo data reset');render()}
    function openModal(type){const modal=document.getElementById('modal-root');const goal=type==='goal',session=type==='session';modal.innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="modal-head"><h2>${goal?'Create a goal':session?'Plan a study session':'Create a task'}</h2><button class="mini-btn" onclick="closeModal()">${icon('x')}</button></div><form class="modal-body form-grid" onsubmit="submitModal(event,'${type}')">${goal?`<label class="form-label">Goal title<input name="title" required placeholder="e.g. Build with confidence"></label><label class="form-label">Why does it matter?<textarea name="description" placeholder="A reason you will remember on a difficult day."></textarea></label>`:session?`<label class="form-label">Session title<input name="title" required placeholder="e.g. Review subnetting"></label><label class="form-label">Subject<select name="subject"><option>Web Development</option><option>Networking</option><option>Cybersecurity</option><option>Mathematics</option></select></label><label class="form-label">Duration (minutes)<input name="estimate" type="number" min="5" value="45" required></label>`:`<label class="form-label">Task title<input name="title" required placeholder="What needs your attention?"></label><label class="form-label">Subject<select name="subject"><option>Web Development</option><option>Networking</option><option>Cybersecurity</option><option>Mathematics</option><option>English</option></select></label><label class="form-label">Due when<select name="due"><option>Today</option><option>Tomorrow</option><option>Wed, Oct 2</option><option>Fri, Oct 4</option></select></label><label class="form-label">Importance<select name="priority"><option>High</option><option>Medium</option><option>Low</option></select></label>`}<div class="modal-foot"><button type="button" class="secondary" onclick="closeModal()">Cancel</button><button class="primary">${icon('check')} Save</button></div></form></div></div>`;refreshIcons()}
    function closeModal(){document.getElementById('modal-root').innerHTML=''}
    function submitModal(e,type){e.preventDefault();const f=new FormData(e.target);if(type==='goal')state.goals.push({id:Date.now(),title:f.get('title'),description:f.get('description')||'A goal worth showing up for.',progress:0,milestones:[['First milestone',false],['Keep going',false]]});else if(type==='session'){toast('Study session planned');closeModal();return}else state.tasks.unshift({id:Date.now(),title:f.get('title'),subject:f.get('subject'),priority:f.get('priority'),due:f.get('due'),estimate:45,progress:0,done:false,difficulty:2});save();closeModal();toast(type==='goal'?'Goal created':'Task created');render()}
    function startFocus(id){timer.taskId=id;timer.seconds=45*60;timer.running=true;clearInterval(timer.interval);timer.interval=setInterval(()=>{if(timer.seconds>0){timer.seconds--;window.StudyFlowStorage.writeTimer({seconds:timer.seconds,taskId:timer.taskId})}else finishFocus()},1000);go('focus')}
    function pauseFocus(){if(!timer.running)return;timer.elapsedSeconds=elapsedFocusSeconds();timer.running=false;timer.runningSince=null;clearInterval(timer.interval);persistTimer();toast('Focus session paused');render()}
    function cancelFocus(){clearInterval(timer.interval);timer={running:false,seconds:0,taskId:1,interval:null};window.StudyFlowStorage.clearTimer();toast('Focus session cancelled');go('dashboard')}
    function finishFocus(){clearInterval(timer.interval);const t=state.tasks.find(x=>x.id===timer.taskId);if(t){t.progress=100;t.done=true}state.studyMinutes+=45;state.notifications.unshift({title:'Focus session complete',body:'45 minutes of deep work added to your week.',time:'Just now',read:false,icon:'check-circle-2'});timer={running:false,seconds:0,taskId:1,interval:null};window.StudyFlowStorage.clearTimer();save();toast('Focus session complete · +45 minutes');go('analytics')}
    function openCommand(){const root=document.getElementById('modal-root'),commands=[['Dashboard','layout-dashboard','dashboard'],['Tasks','check-square-2','tasks'],['Subjects','layers-3','subjects'],['Goals','target','goals'],['Planner','calendar-days','planner'],['Focus','timer','focus'],['Analytics','chart-no-axes-combined','analytics'],['Notifications','bell','notifications'],['Settings','settings-2','settings'],['Create task','plus','create-task'],['Create goal','target','create-goal'],['Start focus','play','start-focus']];root.innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal command" role="dialog" aria-modal="true" aria-label="Command palette"><div class="command-search">${icon('search')}<input autofocus aria-label="Filter commands" placeholder="Search or jump to..." oninput="filterCommands(this.value)"><span class="key">ESC</span></div><div class="command-list" id="command-list">${commands.map((command,index)=>`<button class="command-item ${index===0?'selected':''}" onclick="commandAction('${command[2]}')">${icon(command[1])}<span>${command[0]}</span></button>`).join('')}</div></div></div>`;refreshIcons()}
    function filterCommands(value){const items=[...document.querySelectorAll('.command-item')],matching=items.filter(item=>item.innerText.toLowerCase().includes(value.toLowerCase()));items.forEach(item=>{item.style.display=matching.includes(item)?'flex':'none';item.classList.toggle('selected',item===matching[0])});let empty=document.querySelector('.command-empty');if(!matching.length&&!empty){empty=document.createElement('div');empty.className='command-empty';empty.textContent='No matching commands';document.querySelector('.command-list')?.append(empty)}else if(matching.length)empty?.remove()}
    function commandAction(action){closeModal();if(action==='create-task')openModal('task');else if(action==='create-goal')openModal('goal');else if(action==='start-focus'){const task=recommendation();if(task)startFocus(task.id);else toast('Add an open task before starting focus')}else go(action)}
    function commandKeys(e){if(e.key==='Escape'){closeModal();return}const items=[...document.querySelectorAll('.command-item')].filter(item=>item.style.display!=='none');if(!items.length)return;let selected=items.findIndex(item=>item.classList.contains('selected'));if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();items[selected]?.classList.remove('selected');selected=(selected+(e.key==='ArrowDown'?1:-1)+items.length)%items.length;items[selected].classList.add('selected')}if(e.key==='Enter'){const item=items[selected];if(item)item.click()}}
    function restoreTimer(){try{const saved=window.StudyFlowStorage.readTimer(),task=state.tasks.find(item=>String(item.id)===String(saved?.taskId));if(saved&&Number(saved.seconds)>0&&task){view='focus';timer={running:saved.running!==false,seconds:Number(saved.seconds),elapsedSeconds:Number(saved.elapsedSeconds)||0,startedAt:saved.startedAt||new Date().toISOString(),runningSince:saved.running===false?null:Date.now(),taskId:task.id,interval:null};if(timer.running)runFocusTimer()}else if(saved)window.StudyFlowStorage.clearTimer()}catch(error){window.StudyFlowStorage.clearTimer()}}
    const DEMO_PLANNER_SESSIONS=window.StudyFlowDemoData.plannerSessions;
    if(!Array.isArray(state.plannerSessions)){state.plannerSessions=JSON.parse(JSON.stringify(DEMO_PLANNER_SESSIONS));save()}
    function clone(value){return JSON.parse(JSON.stringify(value))}
    function sessionDuration(session){const [startHour,startMinute]=session.start.split(':').map(Number);const [endHour,endMinute]=session.end.split(':').map(Number);return (endHour*60+endMinute)-(startHour*60+startMinute)}
    function sessionTop(time){const [hour,minute]=time.split(':').map(Number);return ((hour-8)*60+minute)*74/60+12}
    function sessionClass(subject){return subject==='Networking'?'blue':subject==='Mathematics'?'coral':subject==='Cybersecurity'?'lav':''}
    function sessionMarkup(session){const duration=sessionDuration(session),height=Math.max(50,duration*74/60-5);return `<div class="session ${sessionClass(session.subject)}" style="top:${sessionTop(session.start)}px;height:${height}px"><strong>${session.title}</strong><small>${session.subject}</small><small>${session.start} - ${session.end} · ${duration} min</small><div class="session-actions"><button onclick="editSession('${session.id}');event.stopPropagation()" aria-label="Edit ${session.title}">${icon('pencil')}</button><button onclick="deleteSession('${session.id}');event.stopPropagation()" aria-label="Delete ${session.title}">${icon('trash-2')}</button></div></div>`}
    /*
    function planner(){const days=[['Mon','30','2024-09-30'],['Tue','1','2024-10-01'],['Wed','2','2024-10-02'],['Thu','3','2024-10-03'],['Fri','4','2024-10-04'],['Sat','5','2024-10-05'],['Sun','6','2024-10-06']];const sessions=state.plannerSessions||[];const total=sessions.reduce((sum,s)=>sum+sessionDuration(s),0);return `<div class="view">${pageHead('Plan the week','Planner','A calm week is a kind of superpower.','<button class="primary" onclick="openModal(\'session\')">'+icon('plus')+'<span>New session</span></button>')}<section class="panel planner"><div class="week-nav"><div><h3>Sep 30 - Oct 6, 2024</h3><span>Week 40 · ${formatMinutes(total)} planned</span></div><div><button class="secondary" aria-label="Previous week">${icon('chevron-left')}</button><button class="secondary" style="margin-left:5px" aria-label="Next week">${icon('chevron-right')}</button></div></div><div class="calendar"><div></div>${days.map((d,i)=>`<div class="calendar-head ${i===1?'today':''}">${d[0]}<strong>${d[1]}</strong></div>`).join('')}<div class="time-col">${['08:00','09:00','10:00','11:00','12:00','13:00','14:00','15:00','16:00','17:00','18:00','19:00'].map(x=>`<div class="time">${x}</div>`).join('')}</div>${days.map((d)=>`<div class="day-col">${sessions.filter(s=>s.date===d[2]).map(sessionMarkup).join('')}</div>`).join('')}</div><div class="agenda">${days.map(d=>{const daySessions=sessions.filter(s=>s.date===d[2]);return daySessions.length?`<div class="agenda-day">${d[0]} · October ${d[1]}</div>${daySessions.map(s=>`<div class="agenda-session" style="border-color:${sessionClass(s.subject)==='blue'?'var(--blue)':sessionClass(s.subject)==='coral'?'var(--coral)':sessionClass(s.subject)==='lav'?'var(--lav)':'var(--teal)'};background:${sessionClass(s.subject)==='blue'?'#e8f1f5':sessionClass(s.subject)==='coral'?'#fcebe7':sessionClass(s.subject)==='lav'?'#eeebfc':'#e9f3d4'}"><strong>${s.start} - ${s.end} · ${s.title}</strong><small>${s.subject} · ${sessionDuration(s)} min</small><div class="session-actions"><button onclick="editSession('${s.id}')" aria-label="Edit ${s.title}">${icon('pencil')}</button><button onclick="deleteSession('${s.id}')" aria-label="Delete ${s.title}">${icon('trash-2')}</button></div></div>`).join(''):''}).join('')}</div></section></div>`}
    */
    function plannerAgendaMarkup(session){const color=sessionClass(session.subject)==='blue'?'var(--blue)':sessionClass(session.subject)==='coral'?'var(--coral)':sessionClass(session.subject)==='lav'?'var(--lav)':'var(--teal)';const background=sessionClass(session.subject)==='blue'?'#e8f1f5':sessionClass(session.subject)==='coral'?'#fcebe7':sessionClass(session.subject)==='lav'?'#eeebfc':'#e9f3d4';return `<div class="agenda-session" style="border-color:${color};background:${background}"><strong>${session.start} - ${session.end} · ${session.title}</strong><small>${session.subject} · ${sessionDuration(session)} min</small><div class="session-actions"><button onclick="editSession('${session.id}')" aria-label="Edit ${session.title}">${icon('pencil')}</button><button onclick="deleteSession('${session.id}')" aria-label="Delete ${session.title}">${icon('trash-2')}</button></div></div>`}
    function planner(){
      const dates=window.StudyFlowUtils.weekDates(new Date(),plannerWeekOffset),sessions=state.plannerSessions||[],total=sessions.reduce((sum,session)=>sum+sessionDuration(session),0),today=window.StudyFlowUtils.dateKey();
      const days=dates.map(date=>({date,key:window.StudyFlowUtils.dateKey(date),day:window.StudyFlowUtils.formatDate(date,{weekday:'short'}),number:date.getDate()}));
      const headers=days.map(day=>`<div class="calendar-head ${day.key===today?'today':''}">${day.day}<strong>${day.number}</strong></div>`).join('');
      const columns=days.map(day=>`<div class="day-col">${sessions.filter(session=>session.date===day.key).map(sessionMarkup).join('')}</div>`).join('');
      const times=['08:00','09:00','10:00','11:00','12:00','13:00','14:00','15:00','16:00','17:00','18:00','19:00'].map(time=>`<div class="time">${time}</div>`).join('');
      const agenda=days.map(day=>{const daySessions=sessions.filter(session=>session.date===day.key);return daySessions.length?`<div class="agenda-day">${day.day} · ${window.StudyFlowUtils.formatDate(day.date,{month:'long',day:'numeric'})}</div>${daySessions.map(plannerAgendaMarkup).join('')}`:''}).join('');
      const range=`${window.StudyFlowUtils.formatDate(dates[0],{month:'short',day:'numeric'})} - ${window.StudyFlowUtils.formatDate(dates[6],{month:'short',day:'numeric',year:'numeric'})}`;
      return `<div class="view">${pageHead('Plan the week','Planner','A calm week is a kind of superpower.','<button class="primary" onclick="openModal(\'session\')">'+icon('plus')+'<span>New session</span></button>')}<section class="panel planner"><div class="week-nav"><div><h3>${range}</h3><span>${total?formatMinutes(total)+' planned':'No sessions planned yet'}</span></div><div><button class="secondary" aria-label="Previous week" onclick="changePlannerWeek(-1)">${icon('chevron-left')}</button><button class="secondary" aria-label="Next week" onclick="changePlannerWeek(1)">${icon('chevron-right')}</button></div></div><div class="calendar"><div></div>${headers}<div class="time-col">${times}</div>${columns}</div><div class="agenda">${agenda||'<div class="empty"><strong>No sessions this week</strong><span>Add a study block to protect time for focused work.</span></div>'}</div></section></div>`
    }
    function editSession(id){openModal('session',id)}
    function deleteSession(id){const session=state.plannerSessions.find(s=>s.id===id);state.plannerSessions=state.plannerSessions.filter(s=>s.id!==id);save();toast(`${session?session.title:'Session'} deleted`);render()}
    function plannerOptions(selected){const utils=window.StudyFlowUtils,dates=utils.weekDates(new Date(),plannerWeekOffset),firstDay=utils.daysUntilDeadline(utils.dateKey(dates[0]));let selectedDays=utils.daysUntilDeadline(selected);if(selectedDays===null||selectedDays<firstDay-7||selectedDays>firstDay+13)selected=utils.dateKey(new Date());selectedDays=utils.daysUntilDeadline(selected);if(selectedDays!==null&&!dates.some(date=>utils.dateKey(date)===selected))dates.unshift(new Date(`${selected}T00:00:00`));return dates.map(date=>{const key=utils.dateKey(date);return `<option value="${key}" ${selected===key?'selected':''}>${utils.formatDate(date,{weekday:'long',month:'short',day:'numeric'})}</option>`}).join('')}
    function taskDueOptions(selected){const utils=window.StudyFlowUtils,offsets=[0,1,2,5,7],selectedDays=utils.daysUntilDeadline(selected),selectedKey=selectedDays===null?selected:utils.dateKey(utils.addDays(new Date(),selectedDays)),dates=offsets.map(offset=>utils.addDays(new Date(),offset));if(selectedKey&&!dates.some(date=>utils.dateKey(date)===selectedKey))dates.push(new Date(`${selectedKey}T00:00:00`));return dates.map(date=>{const key=utils.dateKey(date);return `<option value="${key}" ${selectedKey===key?'selected':''}>${utils.formatDeadline(key)}</option>`}).join('')}
    function openModal(type,editId=null){const modal=document.getElementById('modal-root');const goal=type==='goal',session=type==='session',editingTask=type==='task'&&editId,editingSession=session&&editId;const task=editingTask?state.tasks.find(t=>t.id===editId):null;const plannerSession=editingSession?state.plannerSessions.find(s=>s.id===editId):null;const title=goal?'Create a goal':session?(plannerSession?'Edit study session':'Plan a study session'):(task?'Edit task':'Create a task');modal.innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="modal-head"><h2>${title}</h2><button class="mini-btn" onclick="closeModal()" aria-label="Close dialog">${icon('x')}</button></div><form class="modal-body form-grid" onsubmit="submitModal(event,'${type}',${editId?`'${editId}'`:'null'})">${goal?`<label class="form-label">Goal title<input name="title" required placeholder="e.g. Build with confidence"></label><label class="form-label">Why does it matter?<textarea name="description" placeholder="A reason you will remember on a difficult day."></textarea>`:session?`<label class="form-label">Session title<input name="title" required value="${plannerSession?.title||''}" placeholder="e.g. Review subnetting"></label><label class="form-label">Subject<select name="subject"><option ${plannerSession?.subject==='Web Development'?'selected':''}>Web Development</option><option ${plannerSession?.subject==='Networking'?'selected':''}>Networking</option><option ${plannerSession?.subject==='Cybersecurity'?'selected':''}>Cybersecurity</option><option ${plannerSession?.subject==='Mathematics'?'selected':''}>Mathematics</option></select></label><label class="form-label">Date<select name="date" required>${plannerOptions(plannerSession?.date||'2024-10-01')}</select></label><div style="display:grid;grid-template-columns:1fr 1fr;gap:10px"><label class="form-label">Start time<input name="start" type="time" required value="${plannerSession?.start||'09:00'}"></label><label class="form-label">End time<input name="end" type="time" required value="${plannerSession?.end||'09:45'}"></label></div><div class="form-error" id="form-error" role="alert"></div>`:`<label class="form-label">Task title<input name="title" required value="${task?.title||''}" placeholder="What needs your attention?"></label><label class="form-label">Subject<select name="subject"><option ${task?.subject==='Web Development'?'selected':''}>Web Development</option><option ${task?.subject==='Networking'?'selected':''}>Networking</option><option ${task?.subject==='Cybersecurity'?'selected':''}>Cybersecurity</option><option ${task?.subject==='Mathematics'?'selected':''}>Mathematics</option><option ${task?.subject==='English'?'selected':''}>English</option></select></label><label class="form-label">Due when<select name="due"><option ${task?.due==='Today'?'selected':''}>Today</option><option ${task?.due==='Tomorrow'?'selected':''}>Tomorrow</option><option ${task?.due==='Wed, Oct 2'?'selected':''}>Wed, Oct 2</option><option ${task?.due==='Fri, Oct 4'?'selected':''}>Fri, Oct 4</option></select></label><label class="form-label">Importance<select name="priority"><option ${task?.priority==='High'?'selected':''}>High</option><option ${task?.priority==='Medium'?'selected':''}>Medium</option><option ${task?.priority==='Low'?'selected':''}>Low</option></select></label>`}<div class="modal-foot"><button type="button" class="secondary" onclick="closeModal()">Cancel</button><button class="primary">${icon('check')} ${editingTask||editingSession?'Update':'Save'}</button></div></form></div></div>`;refreshIcons()}
    function submitModal(e,type,editId=null){
      e.preventDefault();const form=e.target,values=new FormData(form);
      if(type==='session'){
        const session={id:editId||`session-${Date.now()}`,title:String(values.get('title')||'').trim(),subject:values.get('subject'),date:values.get('date'),start:values.get('start'),end:values.get('end')},message=window.StudyFlowPlanner.validate(session,state.plannerSessions),error=form.querySelector('.form-error');
        if(message){error.textContent=message;error.classList.add('show');return}
        if(editId){const index=state.plannerSessions.findIndex(item=>item.id===editId);if(index>=0)state.plannerSessions[index]=session}else state.plannerSessions.push(session);
        save();closeModal();toast(editId?'Study session updated':'Study session planned');render();return
      }
      if(type==='goal')state.goals.push({id:Date.now(),title:String(values.get('title')||'').trim(),description:String(values.get('description')||'').trim()||'A goal worth showing up for.',progress:0,milestones:[['First milestone',false],['Keep going',false]]});
      else if(type==='task'){
        const previous=editId?state.tasks.find(item=>String(item.id)===String(editId)):null,estimate=Math.min(240,Math.max(5,Number(values.get('estimate'))||previous?.estimate||45));
        const task={id:previous?.id||editId||Date.now(),title:String(values.get('title')||'').trim(),subject:values.get('subject'),priority:values.get('priority'),due:values.get('due'),estimate,progress:previous?.progress||0,done:previous?.done||false,difficulty:previous?.difficulty||2};
        if(previous){const index=state.tasks.findIndex(item=>String(item.id)===String(editId));state.tasks[index]=task}else state.tasks.unshift(task)
      }
      save();closeModal();toast(type==='goal'?'Goal created':editId?'Task updated':'Task created');render()
    }
    function openQuickAdd(){const root=document.getElementById('modal-root');root.innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="modal-head"><h2>Quick add</h2><button class="mini-btn" onclick="closeModal()" aria-label="Close dialog">${icon('x')}</button></div><div class="quick-actions"><button onclick="closeModal();openModal('task')">${icon('check-square-2')}<span><strong>New task</strong><small class="muted">Capture the next thing</small></span></button><button onclick="closeModal();openModal('goal')">${icon('target')}<span><strong>New goal</strong><small class="muted">Choose a longer horizon</small></span></button><button onclick="closeModal();openModal('session')">${icon('calendar-plus')}<span><strong>New planner session</strong><small class="muted">Protect time on your week</small></span></button><button onclick="closeModal();startFocus(recommendation().id)">${icon('timer')}<span><strong>Start focus</strong><small class="muted">Work on your next best move</small></span></button></div></div></div>`;refreshIcons()}
    function decorateTaskActions(){document.querySelectorAll('.table-item').forEach(row=>{const title=row.querySelector('.task-name strong')?.textContent,task=state.tasks.find(item=>item.title===title),actions=row.querySelector('.action-row'),check=row.querySelector('.check');if(task&&check)check.setAttribute('aria-label',`${task.done?'Reopen':'Complete'} ${title}`);if(task&&actions&&!actions.querySelector('[aria-label^="Edit"]')){const edit=document.createElement('button');edit.className='mini-btn';edit.setAttribute('aria-label',`Edit ${title}`);edit.innerHTML=icon('pencil');edit.onclick=()=>openModal('task',task.id);actions.prepend(edit)}const focus=actions?.querySelector('[aria-label="Focus task"]'),remove=actions?.querySelector('[aria-label="Delete task"]');if(focus)focus.setAttribute('aria-label',`Start focus for ${title}`);if(remove)remove.setAttribute('aria-label',`Delete ${title}`)});refreshIcons()}
    function decorateDashboard(){const label=document.querySelector('.move-panel .panel-kicker span');if(label)label.innerHTML=icon('sparkles')+' Your next best move';const viewAll=document.querySelector('.tasks-panel .panel-head a');if(viewAll){const button=document.createElement('button');button.type='button';button.className='panel-link';button.setAttribute('aria-label','View all tasks');button.innerHTML=viewAll.innerHTML;button.onclick=()=>go('tasks');viewAll.replaceWith(button)}refreshIcons()}
    function decorateTaskDeadlines(){document.querySelectorAll('.task-row,.table-item').forEach(row=>{const title=row.querySelector('.task-copy strong,.task-name strong')?.textContent,task=state.tasks.find(item=>item.title===title),deadline=row.querySelector('.task-end small')||(row.classList.contains('table-item')?row.children[3]:null);if(!task||!deadline)return;const days=window.StudyFlowUtils.daysUntilDeadline(task.due);deadline.textContent=window.StudyFlowUtils.formatDeadline(task.due);deadline.classList.add('deadline');deadline.classList.toggle('overdue',days<0);deadline.classList.toggle('due-soon',days>=0&&days<=2);if(row.classList.contains('task-row')&&!row.querySelector('.task-estimate')){const estimate=document.createElement('small');estimate.className='task-estimate';estimate.textContent=`${task.estimate} min`;deadline.after(estimate)}});const empty=document.querySelector('.task-table .empty');if(empty){if(state.tasks.length){empty.querySelector('strong').textContent='No matching tasks';empty.querySelector('span').textContent='Try another search or filter.'}if(!empty.querySelector('button'))empty.insertAdjacentHTML('beforeend','<button class="primary" onclick="openModal(\'task\')">Create task</button>')}}
    function render(){const activeSearch=document.activeElement?.matches('.toolbar .input'),cursor=activeSearch?document.activeElement.selectionStart:null,pages={dashboard,tasks,subjects,goals,planner,focus,analytics,notifications,settings};layout(pages[view]());document.querySelectorAll('.page-head button').forEach(button=>{const label=button.textContent.trim().replace(/\s+/g,' ');if(label&&!button.hasAttribute('aria-label'))button.setAttribute('aria-label',label)});if(view==='tasks')decorateTaskActions();if(view==='dashboard')decorateDashboard();if(view==='tasks'||view==='dashboard')decorateTaskDeadlines();if(view==='focus'&&focusComplete){const streak=document.querySelector('.focus-task .stats-row .stat-card:last-child strong');if(streak)streak.textContent=`${window.StudyFlowAnalytics.studyStreak(state.studySessions||[])} day${window.StudyFlowAnalytics.studyStreak(state.studySessions||[])===1?'':'s'}`}if(activeSearch){const input=document.querySelector('.toolbar .input');input?.focus();input?.setSelectionRange(cursor,cursor)}}
    function focus(){const task=state.tasks.find(x=>x.id===timer.taskId)||recommendation();if(focusComplete)return `<div class="view"><div class="focus-wrap"><div class="eyebrow">Session saved · Nice work</div><h1>Focus session complete.</h1><div class="focus-orb"></div><div class="focus-task"><div class="eyebrow">${task.subject}</div><h2>${task.title}</h2><p>Your attention moved this task forward.</p><div class="stats-row" style="margin-top:22px"><div class="panel stat-card"><div><small>Focused</small><strong>${focusComplete.minutes}m</strong></div><span class="stat-icon">${icon('timer')}</span></div><div class="panel stat-card"><div><small>Added today</small><strong>+${focusComplete.minutes}m</strong></div><span class="stat-icon">${icon('trending-up')}</span></div><div class="panel stat-card"><div><small>Streak</small><strong>7 days</strong></div><span class="stat-icon">${icon('flame')}</span></div></div></div><button class="primary" onclick="focusComplete=null;go('dashboard')">${icon('arrow-left')} Back to dashboard</button></div></div>`;const paused=!timer.running&&timer.seconds>0;return `<div class="view"><div class="focus-wrap"><div class="eyebrow">Quiet room · ${timer.running?'In session':paused?'Paused':'Ready when you are'}</div><h1>${timer.running?'Stay with it.':paused?'Pick it back up.':'Make room for deep work.'}</h1><div class="focus-orb"></div><div class="timer-label">${timer.running||paused?'Focused on':'Next up'}</div><div class="timer">${timer.running||paused?formatTimer(timer.seconds):'45:00'}</div><div class="focus-task"><div class="eyebrow">${task.subject}</div><h2>${task.title}</h2><p>${timer.running?'One clear block. Nothing else needs you right now.':paused?'Your session is saved. Resume when you are ready.':'A focused 45 minute block will move this task forward.'}</p></div><div class="focus-controls">${timer.running?`<button class="secondary" onclick="pauseFocus()">${icon('pause')} Pause</button><button class="primary" onclick="finishFocus()">${icon('check')} Finish session</button>`:paused?`<button class="primary" onclick="resumeFocus()">${icon('play')} Resume</button><button class="secondary" onclick="finishFocus()">${icon('check')} Finish</button>`:`<button class="primary" onclick="startFocus(${task.id})">${icon('play')} Start focus</button>`}<button class="secondary" onclick="cancelFocus()">${icon('x')} Cancel</button></div></div></div>`}
    function elapsedFocusSeconds(){return (timer.elapsedSeconds||0)+(timer.running&&timer.runningSince?Math.floor((Date.now()-timer.runningSince)/1000):0)}
    function persistTimer(){window.StudyFlowStorage.writeTimer({seconds:timer.seconds,taskId:timer.taskId,startedAt:timer.startedAt,elapsedSeconds:elapsedFocusSeconds(),running:timer.running})}
    function runFocusTimer(){clearInterval(timer.interval);timer.interval=setInterval(()=>{if(timer.seconds>0){timer.seconds--;timer.elapsedSeconds=elapsedFocusSeconds();timer.runningSince=Date.now();persistTimer();const display=document.querySelector('.timer');if(display)display.textContent=formatTimer(timer.seconds)}else finishFocus()},1000)}
    function startFocus(id){const task=state.tasks.find(item=>String(item.id)===String(id));if(!task||task.done){toast('Add an open task before starting focus');return}focusComplete=null;id=task.id;const sameTask=timer.taskId===id&&timer.seconds>0&&timer.startedAt;if(!sameTask){timer={running:false,seconds:45*60,elapsedSeconds:0,startedAt:new Date().toISOString(),runningSince:null,taskId:id,interval:null}}timer.running=true;timer.runningSince=Date.now();persistTimer();runFocusTimer();go('focus')}
    function resumeFocus(){if(!timer.taskId){startFocus(recommendation()?.id);return}timer.running=true;timer.runningSince=Date.now();persistTimer();runFocusTimer();render()}
    function finishFocus(){clearInterval(timer.interval);const durationSeconds=elapsedFocusSeconds(),minutes=Math.max(1,Math.round(durationSeconds/60)),task=state.tasks.find(item=>String(item.id)===String(timer.taskId)),endedAt=new Date().toISOString();if(task){task.progress=100;task.done=true}state.studySessions=state.studySessions||[];state.studySessions.push({id:`focus-${Date.now()}`,taskId:task?.id||timer.taskId,subject:task?.subject||'Unassigned',startedAt:timer.startedAt||endedAt,endedAt,duration:minutes,durationSeconds,completed:true});state.notifications.unshift({title:'Focus session complete',body:`${minutes} minute${minutes===1?'':'s'} of focused study recorded.`,time:'Just now',read:false,icon:'check-circle-2'});focusComplete={minutes};timer={running:false,seconds:0,elapsedSeconds:0,startedAt:null,runningSince:null,taskId:task?.id||null,interval:null};window.StudyFlowStorage.clearTimer();save();toast(`Focus session complete · ${minutes} min recorded`);go('focus')}
    function cancelFocus(){clearInterval(timer.interval);timer={running:false,seconds:0,elapsedSeconds:0,startedAt:null,runningSince:null,taskId:null,interval:null};focusComplete=null;window.StudyFlowStorage.clearTimer();toast('Focus session cancelled');go('dashboard')}
    function resetData(){state=clone(seed);window.state=state;state.plannerSessions=clone(DEMO_PLANNER_SESSIONS);focusComplete=null;window.StudyFlowStorage.clearTimer();save();toast('Demo data reset');render()}
    document.addEventListener('click',e=>{const quick=e.target.closest('[aria-label="Quick add"]');if(quick){e.preventDefault();e.stopPropagation();openQuickAdd()}},true);
    document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openCommand()}if(e.key==='Escape')closeModal()});
    document.addEventListener('keydown',commandKeys);
    restoreTimer();render();
